INSERT INTO `profile` (`id`, `displayName`, `legalName`, `city`, `country`, `timezone`, `careerStartDate`, `headlineEn`, `headlineVi`, `subheadlineEn`, `subheadlineVi`, `bioEn`, `bioVi`, `languagesEn`, `languagesVi`, `heroKickerEn`, `heroKickerVi`, `headlineAccentEn`, `headlineAccentVi`, `avatarId`, `resumeEnId`, `resumeViId`, `phone`, `createdAt`, `updatedAt`)
VALUES
  (1, 'Parker Vu', 'Vu Van Hung (Hung Vu Van)', 'Hanoi (Nam Tu Liem)', 'Vietnam', 'Asia/Ho_Chi_Minh', '2021-01-01', 'Frontend developer for data-heavy products', 'Frontend developer cho các sản phẩm nhiều dữ liệu', 'I build rating platforms, back offices and sales tools with Vue 3, Nuxt and TypeScript. I care about clean structure and forms that do not lose data.', 'Mình làm nền tảng rating, back office và công cụ cho sales bằng Vue 3, Nuxt, TypeScript. Mình chú trọng cấu trúc code gọn và form không làm mất dữ liệu.', 'I started in 2021 as a fullstack developer on a data migration tool (Flask, Laravel, Vue 2). Then I moved to frontend: Samsung SDS platforms at CMC Global, Particula at Kobizo, and Central Food Wholesale portals through CMC Global.

At Kobizo I led the frontend move from v1 to v2 on Nuxt 3 and was the top contributor on the repo. I like breaking big migrations into slices, and I write down the conventions so the team can follow them.', 'Mình bắt đầu từ 2021, làm fullstack cho một tool migrate dữ liệu (Flask, Laravel, Vue 2). Sau đó mình chuyển hẳn sang frontend: các platform của Samsung SDS ở CMC Global, Particula ở Kobizo, rồi các portal của Central Food Wholesale qua CMC Global.

Ở Kobizo, mình dẫn việc chuyển frontend từ v1 sang v2 trên Nuxt 3 và là người commit nhiều nhất repo. Mình thích chia migration lớn thành từng phần nhỏ, và luôn viết lại convention để cả team làm theo.', 'Vietnamese (native), English (working, TODO confirm level)', 'Tiếng Việt (bản ngữ), tiếng Anh (dùng trong công việc, TODO xác nhận mức độ)', '> Frontend · Vue/Nuxt/TS', '> Frontend · Vue/Nuxt/TS', 'data-heavy', 'nhiều dữ liệu', NULL, NULL, NULL, '<phone>', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3))
ON DUPLICATE KEY UPDATE
  `displayName` = VALUES(`displayName`),
  `legalName` = VALUES(`legalName`),
  `city` = VALUES(`city`),
  `country` = VALUES(`country`),
  `timezone` = VALUES(`timezone`),
  `careerStartDate` = VALUES(`careerStartDate`),
  `headlineEn` = VALUES(`headlineEn`),
  `headlineVi` = VALUES(`headlineVi`),
  `subheadlineEn` = VALUES(`subheadlineEn`),
  `subheadlineVi` = VALUES(`subheadlineVi`),
  `bioEn` = VALUES(`bioEn`),
  `bioVi` = VALUES(`bioVi`),
  `languagesEn` = VALUES(`languagesEn`),
  `languagesVi` = VALUES(`languagesVi`),
  `heroKickerEn` = VALUES(`heroKickerEn`),
  `heroKickerVi` = VALUES(`heroKickerVi`),
  `headlineAccentEn` = VALUES(`headlineAccentEn`),
  `headlineAccentVi` = VALUES(`headlineAccentVi`),
