INSERT INTO `experience` (`id`, `company`, `companyUrl`, `location`, `employmentType`, `roleEn`, `roleVi`, `summaryEn`, `summaryVi`, `highlightsEn`, `highlightsVi`, `startDate`, `endDate`, `sortOrder`, `isVisible`, `createdAt`, `updatedAt`)
VALUES
  (1, 'CMC Global', NULL, 'Hanoi, Vietnam (TODO confirm onsite/remote)', 'FULL_TIME', 'Frontend Developer', 'Frontend Developer', 'Frontend on two internal portals for Central Food Wholesale: the CDP Back Office and the Sales CRM.', 'Làm frontend cho hai portal nội bộ của Central Food Wholesale: CDP Back Office và Sales CRM.', '- Built the field configuration screen for customer verification (LOCK / VERIFY / OPEN for 205 fields).
- Applied that config to the customer info form, with a confirm step before VERIFY changes are sent.
- Built the visit-route review UI for sales: draft edits, frozen completed stops, drag and drop on iPad.
- Built the first version of the AI recommendation tab (UI on a mock service).', '- Làm màn field configuration cho customer verification (LOCK / VERIFY / OPEN cho 205 field).
- Áp config đó vào form thông tin khách hàng, có bước xác nhận trước khi gửi thay đổi VERIFY.
- Làm UI review tuyến viếng thăm cho sales: sửa dạng draft, khóa điểm đã viếng thăm, kéo thả chạy được trên iPad.
- Làm bản đầu của tab AI recommendation (UI chạy trên service mock).', '2026-07-01', NULL, 0, 1, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (2, 'Kobizo', NULL, 'TODO', 'FULL_TIME', 'Frontend Developer (main frontend on Particula)', 'Frontend Developer (frontend chính của Particula)', 'Main frontend developer on Particula, a rating and analytics platform for tokenized real-world assets.', 'Frontend chính của Particula, nền tảng rating và phân tích cho tài sản thực được token hóa.', '- Led the v1 to v2 frontend migration on Nuxt 3. The legacy module tree went from 70 modules to 11.
- Top contributor: about 416 of 1,791 commits on main.
- Owned Report Generation Config and the Financial Statement module.
- Set 1-hour staleTime caching across 52 queries.
- Set up Playwright and data-test hooks on key flows.', '- Dẫn việc migrate frontend từ v1 sang v2 trên Nuxt 3. Phần module cũ giảm từ 70 xuống 11.
- Commit nhiều nhất repo: khoảng 416 trên 1.791 commit ở main.
- Phụ trách Report Generation Config và module Financial Statement.
- Cache staleTime 1 giờ cho 52 query.
- Dựng Playwright và gắn data-test cho các luồng chính.', '2024-02-01', '2025-12-01', 1, 1, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (3, 'CMC Global', NULL, 'Hanoi, Vietnam', 'FULL_TIME', 'Frontend Developer', 'Frontend Developer', 'Frontend on MSP App Expansion and MSP Advanced for Samsung SDS, working with a Korean team.', 'Làm frontend cho MSP App Expansion và MSP Advanced của Samsung SDS, làm việc cùng team Hàn Quốc.', '- Built frontend features with Vue 2 and the Lego framework.
- Worked daily with the Korean team.
- Fixed bugs and wrote unit tests.', '- Làm tính năng frontend bằng Vue 2 và Lego framework.
- Làm việc hằng ngày với team Hàn Quốc.
- Fix bug và viết unit test.', '2022-07-01', '2024-06-01', 2, 1, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (4, 'LitGroup', NULL, 'TODO', 'FULL_TIME', 'Frontend Developer', 'Frontend Developer', 'Frontend for a data migration tool used by US and UK store owners.', 'Làm frontend cho tool migrate dữ liệu, khách hàng ở Mỹ và Anh.', '- Built the migration tool UI with Vue 2 and TypeScript.
- Managed large migration state with Pinia.
- Fixed UI issues reported by customers.', '- Làm UI tool migrate bằng Vue 2 và TypeScript.
- Quản lý state migration lớn bằng Pinia.
- Fix lỗi UI khách hàng báo.', '2022-01-01', '2022-06-01', 3, 1, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (5, 'LitGroup', NULL, 'TODO', 'FULL_TIME', 'Backend Developer', 'Backend Developer', 'Backend for the same migration tool, with Flask and Laravel.', 'Làm backend cho chính tool migrate đó, bằng Flask và Laravel.', '- Built and maintained APIs for Shopify, BigCommerce, WooCommerce and Magento.
- Helped customers fix migration errors, like unsupported custom data.
- Worked on the Laravel management system.', '- Viết và duy trì API cho Shopify, BigCommerce, WooCommerce, Magento.
- Hỗ trợ khách xử lý lỗi migrate, ví dụ dữ liệu custom không được hỗ trợ.
- Tham gia hệ thống quản lý viết bằng Laravel.', '2021-01-01', '2021-12-01', 4, 1, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3))
ON DUPLICATE KEY UPDATE
