INSERT INTO `principle` (`id`, `titleEn`, `titleVi`, `bodyEn`, `bodyVi`, `iconKey`, `sortOrder`, `isVisible`, `createdAt`, `updatedAt`)
VALUES
  (1, 'Migrate in slices', 'Migrate từng phần', 'Big rewrites fail. I move one module at a time and keep the app shippable.', 'Viết lại một lần dễ hỏng. Mình chuyển từng module một, app lúc nào cũng deploy được.', 'layers', 0, 1, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (2, 'Write the conventions down', 'Viết convention ra giấy', 'A STRUCTURE.md and a scaffold command beat a long review thread.', 'Một file STRUCTURE.md và một lệnh scaffold hiệu quả hơn nhiều vòng review.', 'book-open', 1, 1, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (3, 'Never lose the user''s edits', 'Không làm mất dữ liệu người dùng', 'Drafts, diff-only saves, version checks and unsaved-change guards.', 'Draft, chỉ gửi phần thay đổi, check version và chặn rời trang khi chưa lưu.', 'shield-check', 2, 1, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3))
