INSERT INTO `page` (`key`, `seoTitleEn`, `seoTitleVi`, `seoDescriptionEn`, `seoDescriptionVi`, `createdAt`, `updatedAt`)
VALUES
  ('HOME', 'Parker Vu · Senior Frontend Engineer', 'Parker Vu · Senior Frontend Engineer', 'Senior frontend engineer. 5 years shipping data-dense product UIs.', 'Kỹ sư frontend. 5 năm xây dựng giao diện sản phẩm nhiều dữ liệu.', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('ABOUT', 'About', 'Giới thiệu', 'Parker Vu — senior frontend engineer in Hanoi.', 'Parker Vu — kỹ sư frontend tại Hà Nội.', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('PROJECTS', 'Work', 'Việc đã làm', 'Selected case studies.', 'Các case study đã chọn.', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('NOTES', 'Notes', 'Ghi chú', 'Writing about migrations, testing, and frontend craft.', 'Viết về migration, kiểm thử, và nghề frontend.', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('CONTACT', 'Contact', 'Liên hệ', 'Let''s talk about your product.', 'Nói về sản phẩm của bạn.', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3))
